namespace Digester.Core;

public sealed partial class Store
{
    public void RecordFailure(string kind, long id, string key)
    {
        lock (gate) Execute("INSERT OR REPLACE INTO task_failures(kind,id,error_key) VALUES(@p0,@p1,@p2)", kind, id, key);
        Journal.Write("task_failed", new { kind, id, error_key = key is "google-auth" or "tg-auth" or "codex-failed" ? key : "operation" });
    }

    public int ResumeYouTubeJobs(string playlist)
    {
        var resumed = 0;
        Transaction(() =>
        {
            resumed = Execute("""
                UPDATE jobs SET stage='pending',error=NULL,attempts=0,due=0
                WHERE playlist=@p0 AND active=1 AND stage='attention'
                AND (id IN (SELECT id FROM task_failures WHERE kind='job' AND error_key='google-auth')
                  OR error='Your YouTube connection has expired. Reconnect YouTube from the Digester menu.')
                AND NOT EXISTS(SELECT 1 FROM parts WHERE job_id=jobs.id AND state IN ('unknown','sending'))
                """, playlist);
            resumed += Execute("""
                UPDATE resends SET stage='queued',error=NULL,attempts=0,due=0
                WHERE stage='attention' AND job_id IN (SELECT id FROM jobs WHERE playlist=@p0)
                AND id IN (SELECT id FROM task_failures WHERE kind='resen [...]  = resumed });
        return resumed;
    }

    public void RetryJob(long id)
    {
        Transaction(() =>
        {
            var job = GetJob(id) ?? throw new AppException("The video was not found.");
            if (job.Stage is not ("attention" or "retry")) throw new AppException("This task cannot be retried now.");
            if (Parts(id).Any(p => p.State is "unknown" or "sending")) throw new UncertainSend(BotReplies.DeliveryUncertain);
            Update(id, ("stage", Parts(id).Count > 0 ? "ready" : "pending"), ("error", null), ("attempts", 0), ("due", 0));
        });
        Journal.Write("retry_requested", new { kind = "job", id });
    }
}

