namespace Digester.Core;

public sealed record ExtractionProgress(DateTimeOffset Started, DateTimeOffset Updated, string Step, string Result,
    double CompletedSeconds = 0, double DurationSeconds = 0)
{
    public string Describe(DateTimeOffset now)
    {
        var stage = Step switch
        {
            "metadata" => "Reading video details",
            "captions" or "caption" => "Reading subtitles",
            "audio" or "audio_download" => "Downloading audio",
            "audio_conversion" => "Preparing audio",
            "model" => "Loading speech model",
            "transcription" => "Transcribing audio",
            "extraction" when Result == "completed" => "Transcript ready",
            _ => "Getting transcript"
        };
        var progress = DurationSeconds > 0 && CompletedSeconds > 0
            ? $" · {Math.Min(100, CompletedSeconds / DurationSeconds * 100):0}% ({CompletedSeconds / 60:0}/{DurationSeconds / 60:0} min)" : "";
        return stage + progress + $" · elapsed {Math.Max(0, (int)(now - Started).TotalMinutes)} min";
    }

    public static ExtractionProgress? Read(string data, string video)
    {
        try
        {
            var path = Path.Combine(data, "activity", video + ".json");
            return File.Exists(path) ? Json.Read<ExtractionProgress>(File.ReadAllText(path)) : null;
