namespace Digester.Core;

public sealed class ConnectionHealth(TimeSpan delay)
{
    private DateTimeOffset? failedAt;
    private bool reported;
    public bool Failure(DateTimeOffset now)
    {
        failedAt ??= now;
        if (reported || now - failedAt < delay) return false;
        reported = true;
        return true;
    }
    public bool Recover()
    {
        var notify = reported;
        failedAt = null; reported = false;
        return notify;
    }
}

