namespace Digester.Core;

public sealed partial class Store
{
    public MaterialContext? MaterialForMessage(long messageId)
    {
        lock (gate)
        {
            var job = Query("SELECT job_id FROM parts WHERE message_id=@p0 AND state='sent'", messageId).FirstOrDefault();
            if (job != null)
            {
                var id = (long)job["job_id"]; var source = GetJob(id)!;
                return new("https://www.youtube.com/watch?v=" + source.VideoId, SentText(Parts(id)));
            }
            var resend = Query("SELECT resend_id FROM resend_parts WHERE message_id=@p0 AND state='sent'", messageId).FirstOrDefault();
            if (resend != null)
            {
                var id = (long)resend["resend_id"]; var source = GetJob(GetResend(id)!.JobId)!;
                return new("https://www.youtube.com/watch?v=" + source.VideoId, SentText(ResendParts(id)));
            }
            var inbox = Query("SELECT inbox_id FROM inbox_parts WHERE message_id=@p0 AND state='sent'", messageId).FirstOrDefault();
            if (inbox == null) return null;
            var requestId = (long)inbox["inbox_id"]; var request = GetInbox(requestId)!;
            if (request.Kind == "link") return new(request.Payload, SentText(InboxParts(requestId)));
            var context = ContextualRequest.Read(request.Payload);
            return context == null ? null : context.SavedMaterial with
            { Summary = context.SavedMaterial.Summary + "\n\nPrevious question: " + context.OwnerRequest + "\nPrevious answer: " + SentText(InboxParts(requestId)) };
        }
    }

    private static string SentText(List<DeliveryPart> parts) => string.Join("\n\n", parts.Where(p => p.State == "sent").Select(p => p.Text));
}

